    if(action==='close'){closeDialog();return;}if(action==='native-back'){nativeBack();return;}if(action==='flow-back'){showFlowStep('usd');return;}if(action==='native-done'){closeDialog();selectView('consolidated');var consolidatedTab=host().querySelector('[data-pl-view="consolidated"]');if(consolidatedTab)consolidatedTab.focus({preventScroll:true});return;}if(menuAction(action,target))return;if(action==='preview'){previewAccount();return;}if(action==='monthly'){selectView('monthly');return;}
