  function refreshQuote(force){if(!visible(host())||!window.JPWMarket||!JPWMarket.usdBrl)return;var stamp=generation;JPWMarket.usdBrl.refresh(force).then(function(){if(stamp!==generation||!visible(host()))return;var box=host().querySelector('[data-pl-quote-box]');if(box)box.innerHTML=quoteHTML();if(dialog&&dialog.__native){syncNativeForm();}else if(!dialog)render();});}
  function refreshHistorical(){
    var market=window.JPWMarket&&JPWMarket.usdBrl;if(!visible(host())||!market||!market.historical||!selectedMonth||selectedMonth>=monthNow())return;
    if(historicalPending)historicalPending.abort();var controller=new AbortController();historicalPending=controller;
    var stamp=generation,month=selectedMonth,scope=JSON.stringify(api.queries.token(accountId||undefined));notice='Consultando referência histórica de '+monthLabel(month)+'.';
    market.historical(month,{signal:controller.signal}).then(function(q){
      if(controller.signal.aborted||stamp!==generation||!visible(host())||selectedMonth!==month||scope!==JSON.stringify(api.queries.token(accountId||undefined)))return;
      historicalPending=null;if(q&&Number.isFinite(q.rate)){historicalQuotes[month]=q;notice='Referência histórica '+q.referenceDate+' · '+q.source+'.';}else notice='Referência histórica indisponível. Os valores em USD permanecem disponíveis.';render();
    }).catch(function(){if(controller.signal.aborted||stamp!==generation||!visible(host()))return;historicalPending=null;notice='Referência histórica indisponível.';render();});
  }
  function selectView(next){if(next!==view&&!resolveInline(function(){selectView(next);}))return false;if(next==='monthly'&&view!=='monthly')readMonthlyPrefs();if(next==='reference'||next==='accounts')next='consolidated';if(!Object.prototype.hasOwnProperty.call(views,next))return false;closeMenu();closeDialog();if(Object.prototype.hasOwnProperty.call(viewAccounts,view))viewAccounts[view]=accountId;view=next;accountId=Object.prototype.hasOwnProperty.call(viewAccounts,next)?viewAccounts[next]:accountId;if((next==='monthly'||next==='reference')&&!accountId)accountId=viewAccounts.consolidated||activeAccounts()[0]&&activeAccounts()[0].id||'';render(true);return true;}
  function openMonthlyContext(target){
    if(monthlyContextPending)monthlyContextPending(false);
    return new Promise(function(resolve){
      var stamp=generation,base=null,settled=false,guardCleanups=[];
      function finish(accepted){if(settled)return;settled=true;guardCleanups.splice(0).forEach(function(cleanup){cleanup();});if(monthlyContextPending===finish)monthlyContextPending=null;resolve(accepted===true);}
      monthlyContextPending=finish;
      function valid(){
        if(settled||stamp!==generation||!target||typeof target.accountId!=='string'||typeof target.planId!=='string'||
          api.engine.monthKey(target.month)!==target.month||window.JPWModuleAvailability?.canAccess('planning')===false)return false;
        var a=api.queries.account(target.accountId),t=api.queries.token(target.accountId);
        if(!a||a.active!==true||a.plan?.id!==target.planId||target.month<a.plan.startMonth||target.month>api.engine.addMonths(a.plan.startMonth,119))return false;
        if(base===null)base=JSON.stringify(t);
        return base===JSON.stringify(t);
      }
      function waitForGuard(){
        var box=document.querySelector('dialog[open]:not(#notificationCenter)');
        if(!box){finish(false);return;}
        var closed=function(){queueMicrotask(function(){if(!box.open&&!settled)finish(false);});};
        box.addEventListener('close',closed);box.addEventListener('cancel',closed);
        guardCleanups.push(function(){box.removeEventListener('close',closed);box.removeEventListener('cancel',closed);});
      }
      function apply(){
        if(!valid()){finish(false);return;}
        var plan={primary:'planning',screen:'planning',action:'context',localView:{surface:'planning',view:'monthly'}};
        if(!resolveInline(apply)){waitForGuard();return;}
        for(var owner of [window.JPWForex?.executionBoardUI,window.JPWForex?.accountsUI]){
          if(owner?.guardNavigation&&owner.guardNavigation(plan,apply)===false){waitForGuard();return;}
        }
        // Consent never refreshes the captured identity/revision. A changed
        // context requires another explicit attempt against the current data.
        if(!valid()||window.JPWNavigation?.navigateLocal('planning','monthly')!==true||!valid()){finish(false);return;}
        accountId=target.accountId;viewAccounts.monthly=target.accountId;selectedMonth=target.month;expandedMonth=target.month;
        selectedYear='';monthlyPrefs.fromCurrent=false;
        notice='Exibindo '+monthLabel(target.month)+' de '+api.queries.account(target.accountId).name+'. Filtros ajustados para mostrar este mês; suas preferências salvas foram preservadas. Nenhum registro foi alterado.';
        render(true);
        var trigger=host()?.querySelector('[data-pl-select-month="'+target.month+'"]');
        if(trigger){trigger.focus({preventScroll:true});trigger.scrollIntoView({block:'nearest',inline:'nearest'});}
        finish(!!trigger);
      }
      if(!valid()||document.querySelector('dialog[open]:not(#notificationCenter)')){finish(false);return;}
      apply();
    });
  }
  function deactivate(){if(monthlyContextPending)monthlyContextPending(false);cancelInline();closeInlineGuard();closeMenu();stopMonthlyLayout();generation++;quoteRequested=false;if(historicalPending){historicalPending.abort();historicalPending=null;}closeDialog();}
  function discardDrafts(){cancelInline();drafts.clear();closeDialog();notice='Rascunhos descartados.';render(true);}
  function reset(){deactivate();drafts.clear();accountId='';selectedMonth='';selectedYear='';expandedMonth='';view='start';viewAccounts={consolidated:'',monthly:'',reference:''};notice='';historicalQuotes={};monthlyPrefs={version:1,highlightPast:true,fromCurrent:false};monthlyPrefsBlocked=false;monthlyPrefsNotice='';}
  function backupDrafts(clear){
    if(clear){reset();return [];}
    var fieldsAllowed=['unit','value','acknowledged','name','broker','login','server','startMonth','startYear','startMonthNumber','newPlan','initialUsd','profileId','monthlyContributionUsd','adequateValue','adequateCurrency','idealValue','idealCurrency','replaceFuture','confirmation','usd','brl','rate','contributionUsd','confirmFlows','reason','flowMonth','resetScope','resetAccountId','resetUnderstood','stopAfter','stopImpactLimit','adequateQuoteSnapshot','idealQuoteSnapshot','adequateRefreshIntent','idealRefreshIntent'];
    return Array.from(drafts.entries()).filter(function(entry){return entry[1].dirty;}).map(function(entry){
      var key=entry[0],draft=entry[1],fields={};fieldsAllowed.forEach(function(name){var value=draft.fields[name];if(typeof value==='string'||typeof value==='boolean')fields[name]=value;});
      // The backup payload stays opaque/read-only and reuses existing input
      // names; preview/consent/token state never grants permission through export.
      if(key.split(':')[0]==='finalize'){
        if(typeof draft.fields.closureResultUnit==='string')fields.unit=draft.fields.closureResultUnit;
        if(typeof draft.fields.closureResultValue==='string')fields.value=draft.fields.closureResultValue;
      }
      var context={accountId:draft.token.accountId,planId:draft.token.planId,action:key.split(':')[0],key:key,formVersion:1};
      return {provider:'patrimonial-planning',version:1,label:'Planejamento — '+(views[view]||'rascunho')+' — '+context.action+' — '+(context.accountId||'nova conta'),context:context,
        baseReference:JSON.stringify({accountId:context.accountId,planId:context.planId,revision:draft.token.revision,planRevision:draft.token.planRevision}),
        text:JSON.stringify({formVersion:1,fields:fields})};
    });
  }
  api.ui=Object.freeze({guardNavigation:guardNavigation,render:render,selectView:selectView,openMonthlyContext:openMonthlyContext,getView:function(){return view;},hasPendingWork:function(){return Array.from(drafts.values()).some(function(d){return d.dirty;});},deactivate:deactivate,reset:reset,discardDrafts:discardDrafts,backupDrafts:backupDrafts});
